<?php
declare(strict_types=1);
$platform=dirname(__DIR__);$server=$platform.'/plugins/tools/mcp-host/server.php';$mcpData=$root.'/mcp-host-e2e-data';$env=getenv();if(!is_array($env))$env=[];$env['DCP_USER_DATA_DIR']=$mcpData;$env['DCP_MODE']='desktop';
$requests=[
 ['jsonrpc'=>'2.0','id'=>1,'method'=>'initialize','params'=>['protocolVersion'=>'2024-11-05']],
 ['jsonrpc'=>'2.0','id'=>2,'method'=>'tools/list','params'=>new stdClass()],
 ['jsonrpc'=>'2.0','id'=>3,'method'=>'tools/call','params'=>['name'=>'dcp_terminal_execute','arguments'=>['command'=>'pwd','timeout_seconds'=>5,'shell'=>'bash']]],
 ['jsonrpc'=>'2.0','id'=>4,'method'=>'tools/call','params'=>['name'=>'dcp_create_task','arguments'=>['title'=>'MCP E2E approval contract','description'=>'Task creation must not execute its payload','actions'=>[['type'=>'create_directory','path'=>'mcp-e2e-never-run']]]]],
 ['jsonrpc'=>'2.0','id'=>5,'method'=>'tools/call','params'=>['name'=>'dcp_unknown_tool','arguments'=>new stdClass()]],
];
$pipes=[];$proc=proc_open([PHP_BINARY,$server],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,$platform,$env);if(!is_resource($proc))throw new RuntimeException('Unable to start isolated DCP MCP host.');foreach($requests as $request){$line=json_encode($request,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)."\n";if(fwrite($pipes[0],$line)!==strlen($line))throw new RuntimeException('Unable to write MCP request.');}fclose($pipes[0]);$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);$responses=[];foreach(preg_split('/\r?\n/',trim((string)$stdout)) as $line){$decoded=json_decode($line,true);if(is_array($decoded))$responses[$decoded['id']??'']=$decoded;}
ok($exit===0&&count($responses)===5,'MCP stdio host processes multiple JSON-RPC requests and exits cleanly');ok(($responses[1]['result']['serverInfo']['name']??'')==='DCP Core','MCP initialize returns the DCP Core identity');
ok(($responses[1]['result']['serverInfo']['icons'][0]['mimeType']??'')==='image/png','MCP initialize advertises the DCP logo');ok(count($responses[2]['result']['tools']??[])===34,'MCP tools/list exposes one full terminal tool and no safe terminal alias');$terminalResult=json_decode((string)($responses[3]['result']['content'][0]['text']??''),true);ok(($terminalResult['exit_code']??1)===0,'MCP tools/call dispatches through the single full terminal tool');$taskResult=json_decode((string)($responses[4]['result']['content'][0]['text']??''),true);ok(($taskResult['status']??'')==='approval_required','MCP task creation remains approval-required and does not execute its actions');ok(isset($responses[5]['error'])&&str_contains((string)($responses[5]['error']['message']??''),'Tool not found'),'MCP host returns a JSON-RPC error for unknown tools');
